import { api } from './authService';

const clientService = {
  /** GET /clients */
  getAll: async (params = {}) => {
    const { data } = await api.get('/clients', { params });
    return data?.data ?? data;
  },

  getById: async (id) => {
    const { data } = await api.get(`/clients/${id}`);
    return data?.data ?? data;
  },

  /** POST /clients
   * ✅ FIX : le formulaire envoie { name, email, phone, address }
   *   mais le backend attend { firstName, lastName, email, phone, cin }
   *   On découpe "name" en firstName + lastName automatiquement
   */
  create: async (payload) => {
    const nameParts = (payload.name || '').trim().split(' ');
    const firstName = nameParts[0] || payload.name;
    const lastName  = nameParts.slice(1).join(' ') || firstName;
    const mapped = {
      firstName,
      lastName,
      email: payload.email,
      phone: payload.phone || '',
      cin:   payload.cin   || '',
    };
    const { data } = await api.post('/clients', mapped);
    return data?.data ?? data;
  },

  /** PUT /clients/{id} */
  update: async (id, payload) => {
    const nameParts = (payload.name || '').trim().split(' ');
    const firstName = nameParts[0] || payload.name;
    const lastName  = nameParts.slice(1).join(' ') || firstName;
    const mapped = {
      firstName,
      lastName,
      email: payload.email,
      phone: payload.phone || '',
      cin:   payload.cin   || '',
    };
    const { data } = await api.put(`/clients/${id}`, mapped);
    return data?.data ?? data;
  },

  delete: async (id) => {
    const { data } = await api.delete(`/clients/${id}`);
    return data?.data ?? data;
  },
};

export default clientService;
